/* Pool registry - see pools.h for why this is its own file.
 *
 * The shape, one paragraph (POOLS.md sections 3.1-3.5):
 *
 *   - A pool is a **slot in a registry**, never a first-class value. What the library
 *     hands out is a handle: `{ index, generation }`, a plain copyable value.
 *   - Every slot carries a generation. Dropping a pool bumps its generation, so a handle
 *     that outlived its pool fails the check instead of reading freed memory; the library
 *     turns that into `failure(staleHandle)` with a source position (ruling: a bug traps, a
 *     condition is a value - POOLS.md section 3.3).
 *   - Regions and arena blocks are **one tree**: a pool's parent is either another pool
 *     or the arena level that created it. Dropping a pool drops its whole subtree, and
 *     leaving a block drops every pool still hanging off that level. That is the hook the
 *     generator emits, one line per release point.
 *   - Membership is the whole point: because the owner is the parent (not the handle),
 *     "copy the handle" and "two owners free the same slot" cannot happen, and a free list
 *     cannot grow a cycle out of user data.
 *
 * A pool is **not** a second allocator, and an arena is **not** a stack. The arena is
 * where lifetime comes from (its release point is the block that owns it); a pool-backed
 * container puts a **pointer into that same arena**, the pointer names its pool, and the
 * pool holds the container's data structure. The pool's own bookkeeping - slot table,
 * free list, generation, parent/child links - lives in that arena too, as a tree of
 * pointers; clearing walks the tree and marks the slots reusable. Nothing is freed piece by
 * piece: the arena reclaims everything when its block goes, which is why the pool's
 * lifetime is simply the lifetime of the arena it was created in.
 */

#include "pools.h"

/* The runtime text below is the only copy of this logic: it is what runs, so it is what has
 * to be read and tested. It mentions no arena: the arena is where memory comes from, the
 * pool is the side chain that makes it reusable. Split across several `bufPuts` calls
 * because one literal longer than 4095 characters draws -Woverlength-strings. */
void poolsEmitRuntime(Arena *a, Buf *out) {
    (void)a;
    bufPuts(out, "/* ---- pool registry (POOLS.md) ----\n * A pool is an index here, never a value: the library hands out `{ index, generation }`,\n * and dropping bumps the generation, so a handle that outlived its pool fails a check\n * instead of reading freed memory.\n *\n * The picture: the arena is a chain of blocks and nothing else - it is where memory\n * comes from. A pool is a structure of its own: it links what it holds (nested pools)\n * as a side chain beside the arena, and owns no arena. A zone is the head of one such\n * side chain - a virtual grouping, one per place, holding the pools created there. It\n * is deliberately not embedded in the arena's stack: leaving a place has to enumerate\n * the zone's own chain, and a block rollback must not be able to tear that structure\n * out from under it.\n *\n * `extc_pool_zoneLeaveTo(mark)` pops to a mark rather than popping blindly, so early\n * exits (`return`, `break`, `continue`) cannot leave the stack unbalanced: a leave is\n * always expressed as \"back to the depth this place started at\".\n *\n * Emitted only for a program that declares a pool extern. */\ntypedef struct ExtcPool {\n    uint64_t generation;\n    int64_t  parent;        /* parent pool, or -1 for a root of its zone */\n    int64_t  zone;          /* the zone (place) that owns it */\n    int64_t  firstChild;    /* nested pools: a container of containers */\n    int64_t  nextSibling;   /* the parent's child list */\n    int64_t  zoneNext;      /* the zone's list of pool trees (the side chain) */\n    int64_t  freeNext;      /* the free list of slots */\n    int64_t  live;\n} ExtcPool;\ntypedef struct ExtcZone { int64_t firstPool, parent; } ExtcZone;\nstatic ExtcPool *extc_pools        = NULL;\nstatic int64_t   extc_poolCap      = 0;\nstatic int64_t   extc_poolLiveN    = 0;\nstatic int64_t   extc_poolFreeHead = -1;\nstatic ExtcZone *extc_zones        = NULL;\nstatic int64_t   extc_zoneCap      = 0;\nstatic int64_t   extc_zoneTop      = -1;\nint64_t extc_pool_live(void) { return extc_poolLiveN; }\nint64_t extc_pool_capacity(void) { return extc_poolCap; }\nint64_t extc_pool_zoneDepth(void) { return extc_zoneTop + 1; }\n/* Entering a place: push the head of a side chain and hand back its mark. */\nint64_t extc_pool_zoneEnter(void) {\n    int64_t id = extc_zoneTop + 1;\n    if (id >= extc_zoneCap) {\n        int64_t want = extc_zoneCap ? extc_zoneCap * 2 : 64;\n        ExtcZone *grown = (ExtcZone *)realloc(extc_zones, (size_t)want * sizeof *grown);\n        if (!grown) return -1;\n        extc_zones = grown; extc_zoneCap = want;\n    }\n    extc_zones[id].firstPool = -1;\n    extc_zones[id].parent    = extc_zoneTop;\n    extc_zoneTop = id;\n    return id;\n}\nstatic void extc_pool_freeSelf(int64_t rid) {\n    ExtcPool *r = &extc_pools[rid];\n    r->live = 0; r->parent = -1; r->firstChild = -1;\n    r->freeNext = extc_poolFreeHead;\n    extc_poolFreeHead = rid;\n    extc_poolLiveN--;\n}\nstatic void extc_pool_unlinkZone(int64_t rid) {\n    int64_t zi = extc_pools[rid].zone;\n    if (zi < 0) return;\n");
    bufPuts(out, "    {\n        int64_t *link = &extc_zones[zi].firstPool;\n        while (*link >= 0) {\n            if (*link == rid) { *link = extc_pools[rid].zoneNext; break; }\n            link = &extc_pools[*link].zoneNext;\n        }\n    }\n}\nvoid extc_pool_drop(int64_t rid) {\n    int64_t child, parent;\n    if (rid < 0 || rid >= extc_poolCap || !extc_pools[rid].live) return;\n    child = extc_pools[rid].firstChild;\n    while (child >= 0) {\n        int64_t next = extc_pools[child].nextSibling;\n        extc_pool_drop(child);\n        child = next;\n    }\n    parent = extc_pools[rid].parent;\n    if (parent >= 0) {\n        int64_t *link = &extc_pools[parent].firstChild;\n        while (*link >= 0) {\n            if (*link == rid) { *link = extc_pools[rid].nextSibling; break; }\n            link = &extc_pools[*link].nextSibling;\n        }\n    }\n    /* A pool is on the zone chain whether or not it has a parent, so dropping it\n     * always has to leave that chain -- a stale link would be followed by the next\n     * zone sweep, and the record may already belong to somebody else. */\n    extc_pool_unlinkZone(rid);\n    extc_pool_freeSelf(rid);\n}\n/* A pool is created with its container, inside some place; `parent` is another pool when\n * the container nests one, -1 otherwise. No arena and no level number is passed: the\n * memory a container uses comes from the arena current where it is written, and getting\n * one of those arguments wrong is what made an earlier version drop a live pool. */\nint64_t extc_pool_new(int64_t parent) {\n    int64_t idx, zi = extc_zoneTop;\n    ExtcPool *r;\n    if (zi < 0) return -1;\n    if (extc_poolFreeHead >= 0) {\n        idx = extc_poolFreeHead;\n        extc_poolFreeHead = extc_pools[idx].freeNext;\n    } else {\n        int64_t want = extc_poolCap ? extc_poolCap * 2 : 64, i;\n        ExtcPool *grown = (ExtcPool *)realloc(extc_pools, (size_t)want * sizeof *grown);\n        if (!grown) return -1;\n        for (i = extc_poolCap; i < want; i++) {\n            grown[i].generation = 0; grown[i].parent = -1; grown[i].zone = -1;\n            grown[i].firstChild = -1; grown[i].nextSibling = -1;\n            grown[i].zoneNext = -1; grown[i].freeNext = -1; grown[i].live = 0;\n        }\n        extc_pools = grown; idx = extc_poolCap; extc_poolCap = want;\n    }\n    r = &extc_pools[idx];\n    if (r->live) return -1;\n    r->generation++;\n    r->live = 1; r->parent = parent; r->zone = zi;\n    r->firstChild = -1; r->nextSibling = -1; r->zoneNext = -1;\n    /* TWO CHAINS, attached separately (POOLS.md 7.7). The zone root chain is LIFETIME: a place\n     * releases everything in it, and it has to see every pool, nested or not. The parent\n     * chain is LOGICAL: dropping a container takes the containers nested inside it.\n     * Attaching only the parent chain would hide a nested pool from its own place, so a\n     * pool created in a deeper block would outlive it. */\n    r->zoneNext = extc_zones[zi].firstPool;\n    extc_zones[zi].firstPool = idx;\n    if (parent >= 0) {\n        r->nextSibling = extc_pools[parent].firstChild;\n        extc_pools[parent].firstChild = idx;\n    }\n    extc_poolLiveN++;\n    return idx;\n}\nuint64_t extc_pool_generation(int64_t rid) {\n    if (rid < 0 || rid >= extc_poolCap || !extc_pools[rid].live) return 0;\n    return extc_pools[rid].generation;\n}\n/* Keep the pool, mark its slots reusable: the nested tree is walked and dropped. The\n * memory stays where it is (the arena releases it at the end of the place), so `reset`\n * is about reuse, not about returning memory - which is what makes it cheap to call. */\nvoid extc_pool_reset(int64_t rid) {\n    int64_t child;\n");
    bufPuts(out, "    if (rid < 0 || rid >= extc_poolCap || !extc_pools[rid].live) return;\n    child = extc_pools[rid].firstChild;\n    while (child >= 0) {\n        int64_t next = extc_pools[child].nextSibling;\n        extc_pool_drop(child);\n        child = next;\n    }\n    extc_pools[rid].firstChild = -1;\n}\n/* Leaving a place: drop every zone from the top down to `mark` (the depth this place\n * started at). Explressed as a mark rather than one pop, so a path that skipped a leave\n * still ends up balanced. */\nvoid extc_pool_zoneLeaveTo(int64_t mark) {\n    while (extc_zoneTop >= mark && extc_zoneTop >= 0) {\n        int64_t zi = extc_zoneTop;\n        int64_t rid = extc_zones[zi].firstPool;\n        while (rid >= 0) {\n            int64_t next = extc_pools[rid].zoneNext;\n            extc_pool_drop(rid);\n            rid = next;\n        }\n        extc_zoneTop = extc_zones[zi].parent;\n    }\n}\n");
}
